import logging
import sys
from pathlib import Path

# Add project root to path for src and benchmark_app package imports
sys.path.insert(0, str(Path(__file__).resolve().parent.parent))

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(name)s: %(message)s", datefmt="%H:%M:%S")

from benchmark_app import BenchmarkConfig, BenchmarkRunner, PlotMaker, scan_devices

from src import MandelbrotConfig

logger = logging.getLogger(__name__)
logging.getLogger("numba.cuda.cudadrv.driver").setLevel(logging.WARNING)


def main():
    scan_devices()

    config = BenchmarkConfig(
        mb_config=MandelbrotConfig(
            xmin=-2.0, xmax=1.0,
            ymin=-1.5, ymax=1.5,
            max_iter=100,
            chunk_size=128*2,  # Only relevant for multiprocess calculators
        ),

        calculators=["numpy", "numba", "cupy", "cuda", "multiprocess_numpy", "multiprocess_numba"],
        resolutions=[256, 512, 1024, 2048, 4096, 8192, 16384, 32768, 65536],

        num_runs=3,
        warmup_runs=1,

        breakout_time=5.5,  # Skip higher resolutions if avg time exceeds this (seconds)
    )


    logger.info("Starting benchmark...")
    logger.info(f"Calculators: {config.calculators}")
    logger.info(f"Resolutions: {config.resolutions}")
    logger.info(f"Runs per config: {config.num_runs} (+ {config.warmup_runs} warmup)\n")

    runner = BenchmarkRunner(config)
    results = runner.run()
    runner.save_csv(output_dir=config.output_dir)

    logger.info("Generating plots...")
    plotter = PlotMaker(results, output_dir=config.output_dir)
    plotter.make_all_plots(save=True, show=False)

    logger.info("Done.")


if __name__ == "__main__":
    main()
